set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {DatabaseSync} from 'node:sqlite';import {execFileSync} from 'node:child_process';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {collectDiscoveryHealth} from './src/newsFlow/discoveryHealth.mjs';const root='/var/lib/news-flow/qc-public24-20261123',require=createRequire('/opt/news-flow/current/package.json'),dotenv=require('dotenv'),ES=require('elasticsearch'),sha=x=>createHash('sha256').update(x).digest('hex'),env=dotenv.parse(fs.readFileSync('/etc/news-flow/news.env')),aiEnv=dotenv.parse(fs.readFileSync('/etc/news-flow/ai.env')),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:15000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),registry=await loadNewsRegistry(),paths=JSON.parse(fs.readFileSync(root+'/paths.json')),apply=JSON.parse(fs.readFileSync(root+'/apply-result.json')),health=collectDiscoveryHealth(db,registry.sources.values()),r={at:new Date().toISOString(),services:execFileSync('systemctl',['show','news-flow-seed','news-flow-parse','news-flow-import','-p','Id,MainPID,ActiveState,NRestarts'],{encoding:'utf8'}),aiUsage:db.prepare('SELECT * FROM ai_usage ORDER BY day').all(),aiPolicy:{dailyBudgetUSD:Number(aiEnv.AI_DAILY_BUDGET_USD),dailyMaxCalls:Number(aiEnv.AI_DAILY_MAX_CALLS),model:aiEnv.NEWS_AI_MODEL},paidManualAiCalls:0,cohort:paths.cohort.map(site=>({site,alerts:health.sites.find(s=>s.site===site)?.alerts||[]})),configs:[],controls:[]};
try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;assert(proof.verified&&info.version.number.startsWith('5.6.')&&sha(info.cluster_uuid)===proof.clusterFingerprint);for(const c of apply.frozenControls){const q=c.site==='edition.cnn.com'?JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-recover25-20261122/cnn-qualified.json')):JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-complete27-20261122/qualified-sites.json')).sites.find(s=>s.site===c.site),p=q.pages.find(p=>p.url===c.url&&p.doc),receipt=db.prepare('SELECT * FROM import_receipts WHERE id=?').get(p.doc._id);assert(receipt);const hit=await es.get({index:receipt.es_index,type:receipt.es_type,id:receipt.es_id}),mismatches=['url','title','content','description','publishedDate'].filter(k=>JSON.stringify(hit._source[k])!==JSON.stringify(p.doc._source[k]));r.controls.push({site:c.site,url:c.url,exactMatch:mismatches.length===0,mismatches});}
for(const s of paths.sites){const actual=sha(fs.readFileSync(s.configFile));r.configs.push({site:s.site,unchanged:actual===s.configSha,sha256:actual});}
r.articleStats=db.prepare("SELECT parse_status,error,count(*) n FROM article_links WHERE site='tieudungso.vn' GROUP BY parse_status,error").all();r.failures=db.prepare("SELECT url,error FROM article_links WHERE site='tieudungso.vn' AND parse_status='fail'").all();r.seedStats=db.prepare("SELECT url,status,reason,links_found,new_links,last_at FROM seed_sources WHERE site='tieudungso.vn'").all();r.importsSinceApply=db.prepare("SELECT status,count(*) n FROM import_receipts WHERE url LIKE '%tieudungso.vn/%' AND imported_at>=? GROUP BY status").all(Date.parse(apply.at));r.cnnStats=db.prepare("SELECT parse_status,count(*) n FROM article_links WHERE site='edition.cnn.com' GROUP BY parse_status").all();r.historicalAiUsagePreserved=paths.aiUsageBefore.every(old=>r.aiUsage.some(v=>v.day===old.day&&v.calls===old.calls&&v.usd===old.usd));r.remaining=r.cohort.filter(s=>s.alerts.length).length;r.tieudungsoHealth=r.cohort.find(s=>s.site==='tieudungso.vn');r.verified=r.controls.length===15&&r.controls.every(c=>c.exactMatch)&&r.configs.filter(c=>c.site!=='tieudungso.vn').every(c=>c.unchanged)&&r.configs.find(c=>c.site==='tieudungso.vn').sha256===apply.sha256&&r.historicalAiUsagePreserved&&r.aiPolicy.dailyBudgetUSD===2&&r.aiPolicy.dailyMaxCalls===200&&!r.tieudungsoHealth.alerts.length&&!r.failures.length;fs.writeFileSync(root+'/postcheck.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));
}finally{db.close();es.close();}
