for name in paths native-paths native-inspection candidate-controls tieudungso-qualified apply-result real-flow postcheck deployed-tieudungso last-routes; do
  if test -f "/var/lib/news-flow/qc-public24-20261123/$name.json"; then install -o "$SUDO_USER" -m 0600 "/var/lib/news-flow/qc-public24-20261123/$name.json" "$upload_dir/.qc-public24-$name.json"; fi
done
tar -czf /var/lib/news-flow/qc-public24-20261123/evidence.tar.gz -C /var/lib/news-flow/qc-public24-20261123 evidence
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-public24-20261123/evidence.tar.gz "$upload_dir/.qc-public24-evidence.tar.gz"
sha256sum /var/lib/news-flow/qc-public24-20261123/evidence.tar.gz
